"""Cylindrical worm wheel generated by its matching ZA/ZI helicoid.

Houser & Su (1999), Eqs. 4, 5, 11--13: replace screw rotation by axial
translation, solve the common-normal equation, then express the contact point
in the rotating wheel frame. See docs/technical/worm.md for conventions.
Only Python's standard library is needed; every exporter uses these sections.
"""
from math import pi, sin, cos, tan, atan, asin, acos, atan2, hypot, sqrt

TAU = 2*pi
CHORD = .005


def chord_distance(p,a,b):
    dx,dy = b[0]-a[0],b[1]-a[1]
    norm = dx*dx+dy*dy
    t = max(0.,min(1.,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/norm)) if norm else 0.
    return hypot(p[0]-a[0]-t*dx,p[1]-a[1]-t*dy)


class WormSurface:
    """Analytic screw surface in world +X; wheel axis +Z, centre at (0,-a,0)."""
    def __init__(self, values):
        self.module = m = values['module']
        self.starts = values['starts']
        self.teeth = values['teeth']
        self.rp = values['diameter']/2
        self.k = m*self.starts/2
        self.R = m*self.teeth/2
        self.a = self.rp+self.R
        self.hand = values['worm_hand']
        self.length = values['length']
        self.backlash = values['backlash']
        self.variant = values['variant']
        self.alpha = values['pressure']*pi/180
        self.gamma = atan(self.k/self.rp)
        self.rb = self.rp*cos(atan(tan(self.alpha)/tan(self.gamma)))
        self.tip = self.rp+m
        self.root = self.rp-1.25*m
        # A hob extends the same flanks to give 0.25 mx bottom clearance.
        self.hob_tip = self.rp+1.25*m
        self.reference = pi/2+(self.hand*self.k*pi/2+self.length/2)/self.R

    def half_angle(self, radius, *, cutter=False):
        half = pi/(2*self.starts)+(1 if cutter else -1)*self.backlash/(4*self.k)
        if self.variant == 'za':
            return half-(radius-self.rp)*tan(self.alpha)/self.k
        def inv(r):
            t = sqrt(max(0, (r/self.rb)**2-1))
            return t-atan(t)
        return half+inv(self.rp)-inv(radius)

    def half_derivative(self, radius):
        if self.variant == 'za':
            return -tan(self.alpha)/self.k
        return -sqrt(max(0, radius*radius-self.rb*self.rb))/(self.rb*radius)

    def generator(self, radius, height, side):
        """Unrotated cutter point and normal; side is -1 or +1."""
        y = -sqrt(radius*radius-height*height)
        psi = -pi-asin(height/radius)  # Continuous across height zero.
        u = self.k*(self.hand*(psi+pi/2)-side*self.half_angle(radius, cutter=True))-self.length/2
        derivative = self.half_derivative(radius)
        ny = self.k*side*derivative*y/radius+self.hand*self.k*height/radius**2
        nz = self.k*side*derivative*height/radius-self.hand*self.k*y/radius**2
        return (u, y, height), (1., ny, nz)

    def contact(self, radius, height, side):
        """Wheel point, original generator point/normal, and screw rotation."""
        original, normal = self.generator(radius, height, side)
        u, y, _ = original
        if abs(normal[1]) < 1e-10:
            raise ValueError('Worm wheel envelope has a singular contact normal; reduce face width or lead angle.')
        x = (y+self.rp)/normal[1]
        phi = (u-x)/(self.hand*self.k)
        angle = (u-x)/self.R
        point = (x*cos(angle)+(self.a+y)*sin(angle),
                 -x*sin(angle)+(self.a+y)*cos(angle))
        return point, original, normal, phi


class WheelSection:
    def __init__(self, surface, height):
        self.surface, self.height = s, q = surface, height
        # The blank tip is a torus around the nominal worm root-clearance
        # cylinder. It is not the generated tooth-flank construction.
        self.outer_radius = s.a-sqrt((s.rp-s.module)**2-q*q)
        self.root_radius = s.a-sqrt(s.hob_tip**2-q*q)
        self.starts = {}
        self.ends = {}
        self.flank_ends = {-1:s.hob_tip,1:s.hob_tip}
        self.undercut = False
        for side in (-1, 1):
            minimum = max(abs(q)+1e-7, s.root,
                          s.rb*(1+1e-8) if s.variant == 'zi' else 0)
            previous = s.hob_tip
            candidate,_,normal,_ = s.contact(previous,q,side)
            previous_normal = normal[1]
            last = hypot(*candidate)-self.outer_radius
            bracket = None
            # Follow the first usable branch inward from the cutter tip;
            # never jump across a contact singularity or an undercut loop.
            for i in range(1,65):
                radius = s.hob_tip+(minimum-s.hob_tip)*i/64
                candidate,_,normal,_ = s.contact(radius,q,side)
                if previous_normal*normal[1]<=0:
                    raise ValueError('Worm wheel contact normal crosses a singularity; reduce width or lead angle.')
                previous_normal = normal[1]
                value = hypot(*candidate)-self.outer_radius
                if value >= 0 and last < 0:
                    bracket = radius, previous
                    break
                previous, last = radius, value
            if bracket is None:
                raise ValueError('Worm wheel tip cannot meet the usable generated flank; reduce width or lead angle.')
            lo, hi = bracket
            for _ in range(42):
                mid = (lo+hi)/2
                if hypot(*s.contact(mid,q,side)[0]) > self.outer_radius:
                    lo = mid
                else:
                    hi = mid
            self.starts[side] = (lo+hi)/2
            point, original, normal, _ = s.contact(s.hob_tip,q,side)
            self.ends[side] = (original[1]+s.rp)/normal[1], original[0]
        for side in (-1,1):
            self.trim_undercut(side)
        # A neighbouring hob tooth must leave a positive wheel tooth at the tip.
        if self.angle(self.flank(1,0))-self.angle(self.flank(-1,0)) >= TAU/s.teeth-1e-7:
            raise ValueError('Worm wheel tooth gaps overlap at the face edge; reduce width, pressure angle or backlash.')

    def angle(self, p):
        ref = self.surface.reference
        return ref+(atan2(p[1],p[0])-ref+pi)%TAU-pi

    def flank(self, side, t):
        s = self.surface
        radius = self.starts[side]+(self.flank_ends[side]-self.starts[side])*t
        return s.contact(radius,self.height,side)[0]

    def trim_undercut(self, side):
        """Trim a recut loop using the equal-radius tip-edge sweep intersection."""
        xend,u = self.ends[side]
        if abs(xend)<1e-12:return
        def difference(t):
            p = self.flank(side,t)
            square = p[0]*p[0]+p[1]*p[1]-self.root_radius**2
            if square<0:return None
            x = (1 if xend>0 else -1)*sqrt(square)
            fraction = 1-x/xend
            if not 0<=fraction<=1:return None
            q = self.fillet(side,fraction)
            return self.angle(p)-self.angle(q),fraction
        # Resolve small loops near the common endpoint as well as large ones.
        grid = [j/64 for j in range(64)]+[1-2.**(-j) for j in range(1,22)]
        def radius2(t):
            p=self.flank(side,t)
            return p[0]*p[0]+p[1]*p[1]
        lo,hi=0.,1.
        for _ in range(45):
            left,right=(2*lo+hi)/3,(lo+2*hi)/3
            if radius2(left)<radius2(right):hi=right
            else:lo=left
        minimum=(lo+hi)/2
        edge_radius2=xend*xend+self.root_radius**2
        if radius2(minimum)<edge_radius2-1e-10:
            lo,hi=0.,minimum
            for _ in range(42):
                mid=(lo+hi)/2
                if radius2(mid)>edge_radius2:lo=mid
                else:hi=mid
            entry=(lo+hi)/2
            # The valid equal-radius interval can be much narrower than a
            # uniform grid. Include its boundary and internal minimum.
            grid += [entry+(1-entry)*1e-7,(entry+minimum)/2,minimum]
        grid = sorted(set(grid))
        previous = None
        bracket = None
        for t in grid:
            value = difference(t)
            if value is None:continue
            if previous is not None and value[0]*previous[1]<0:
                bracket = previous[0],t
                break
            if abs(value[0])>1e-12:previous=t,value[0]
        if bracket is None:
            return  # A simple overhanging root is valid without a recut loop.
        lo,hi = bracket
        flo = difference(lo)[0]
        for _ in range(45):
            mid = (lo+hi)/2
            fm = difference(mid)[0]
            if fm*flo>0:lo=mid;flo=fm
            else:hi=mid
        t = (lo+hi)/2
        residual,fraction = difference(t)
        if t>1-1e-6:return  # The shared analytic endpoint is not an undercut.
        p,q = self.flank(side,t),self.fillet(side,fraction)
        if hypot(p[0]-q[0],p[1]-q[1])>1e-7:
            raise ValueError('Unable to resolve worm wheel undercut transition within numerical tolerance.')
        self.flank_ends[side] = self.starts[side]+(self.surface.hob_tip-self.starts[side])*t
        self.ends[side] = xend*(1-fraction),u
        self.undercut = True

    def fillet(self, side, t):
        # Sweep the actual sharp hob-tip edge between its flank characteristic
        # and its cylinder characteristic. A radial/circular shortcut is wrong.
        s = self.surface
        end, u = self.ends[side]
        x = end*(1-t)
        angle = (u-x)/s.R
        return (x*cos(angle)+self.root_radius*sin(angle),
                -x*sin(angle)+self.root_radius*cos(angle))

    def arc(self, root, t):
        if root:
            lo,hi = self.angle(self.fillet(-1,1)),self.angle(self.fillet(1,1))
            radius = self.root_radius
        else:
            lo,hi = self.angle(self.flank(1,0)),self.angle(self.flank(-1,0))+TAU/self.surface.teeth
            radius = self.outer_radius
        angle = lo+(hi-lo)*t
        return radius*cos(angle),radius*sin(angle)

    def curves(self):
        return [lambda t:self.flank(-1,t),lambda t:self.fillet(-1,t),
                lambda t:self.arc(True,t),lambda t:self.fillet(1,1-t),
                lambda t:self.flank(1,1-t),lambda t:self.arc(False,t)]

    def gap(self, counts):
        return [curve(j/count) for curve,count in zip(self.curves(),counts) for j in range(count)]


def wheel_sections(values, *, hole_vertices=0):
    """Return bounded, corresponding wheel contours and honest solver metadata."""
    s = WormSurface(values)
    width = values['width']
    if s.rp <= s.module or width/2 >= .95*(s.rp-s.module):
        raise ValueError('Wheel too wide for the usable worm root-clearance cylinder (half width < 0.95 (rp - mx)).')
    if s.half_angle(s.hob_tip,cutter=True) <= 0:
        raise ValueError('Worm wheel generating hob has a pointed tip; reduce pressure angle or module.')
    cache = {}
    def section(q):
        if q not in cache:
            cache[q] = WheelSection(s,q)
        return cache[q]
    probes = [section(width*(j/4-.5)) for j in range(5)]
    counts = [8,4,4,4,8,4]
    # Refine each curve identically in every section, retaining correspondence.
    for curve_index in range(6):
        for _ in range(6):
            count = counts[curve_index]
            error = 0.
            for p in probes:
                curve = p.curves()[curve_index]
                for j in range(count):
                    a,b,c = curve(j/count),curve((j+1)/count),curve((j+.5)/count)
                    error = max(error,chord_distance(c,a,b))
            if error <= CHORD:
                break
            counts[curve_index] *= 2
        else:
            raise ValueError('Worm wheel flank exceeds the bounded curve refinement limit.')
    levels = [-width/2,0.,width/2]
    for _ in range(7):
        refined = [levels[0]]
        changed = False
        for lo,hi in zip(levels,levels[1:]):
            a,b,c = section(lo).gap(counts),section(hi).gap(counts),section((lo+hi)/2).gap(counts)
            error = max(hypot(z[0]-(x[0]+y[0])/2,z[1]-(x[1]+y[1])/2) for x,y,z in zip(a,b,c))
            if error > CHORD:
                refined.append((lo+hi)/2)
                changed = True
            refined.append(hi)
        levels = refined
        if 2*(sum(counts)*s.teeth+hole_vertices)*(len(levels)-1)+2 > 250000:
            raise ValueError('Worm wheel too detailed (250,000 face limit): reduce width or tooth count.')
        if not changed:
            break
    else:
        raise ValueError('Worm wheel exceeds the bounded face refinement limit.')
    result = []
    for q in levels:
        gap = section(q).gap(counts)
        # Undercut roots can overhang in polar coordinates. Reject actual
        # self-crossings, including the neighbouring tooth, instead of
        # incorrectly rejecting every nonmonotonic polar angle.
        pitch = TAU/s.teeth
        following = [(x*cos(pitch)-y*sin(pitch),x*sin(pitch)+y*cos(pitch)) for x,y in gap]
        chain = gap+following+[(gap[0][0]*cos(2*pitch)-gap[0][1]*sin(2*pitch),gap[0][0]*sin(2*pitch)+gap[0][1]*cos(2*pitch))]
        edges = list(zip(chain,chain[1:]))
        def crossing(a,b,c,d):
            if any(max(a[i],b[i])<min(c[i],d[i])-1e-9 or max(c[i],d[i])<min(a[i],b[i])-1e-9 for i in (0,1)):
                return False
            def side(p,q,r):return (q[0]-p[0])*(r[1]-p[1])-(q[1]-p[1])*(r[0]-p[0])
            return side(a,b,c)*side(a,b,d)<-1e-16 and side(c,d,a)*side(c,d,b)<-1e-16
        for i,(a,b) in enumerate(edges[:len(gap)]):
            if any(crossing(a,b,c,d) for c,d in edges[i+2:]):
                raise ValueError('Worm wheel generated contour crosses itself; reduce width or lead angle.')
        loop = []
        for tooth in range(s.teeth):
            angle = TAU*tooth/s.teeth
            c,sn = cos(angle),sin(angle)
            loop.extend([(x*c-y*sn,x*sn+y*c) for x,y in gap])
        result.append((q,loop))
    return result,dict(method='matching ZA/ZI helicoid envelope with swept hob-tip transitions',
                      conjugate=True,centre_distance_mm=s.a,reference_wheel_radius_mm=s.R,
                      generating_hob_tip_radius_mm=s.hob_tip,root_clearance_mm=.25*s.module,
                      pair_axial_backlash_mm=s.backlash,chord_threshold_mm=CHORD,
                      undercut_trimmed=any(section(q).undercut for q in levels),
                      section_count=len(levels),points_per_tooth=sum(counts),
                      domain='Ideal rigid cylindrical screw; sampled envelope, no strength or manufacturing certification')
